<?php
declare(strict_types=1);
/**
 * Lasting marks (claude/PROPOSAL-HOLLOW-MASTER.md section 7, claude/proposal-stop-perks.md). Behind the setting `stop_marks_open`
 * (default 0): while it is 0 nothing here changes the game; the old meters (decay, 7-day perks) work as before.
 *
 * Bars: three per stop per gnome (repairs, larder, cheer), 0-100, in stop_prog "meter:<bar>" as before. Acts feed them by
 * data/stop_act_bars.txt (generated by claude/tools_export_stop_act_bars.py) with the points of master 7.3, counted on the gnome's
 * game day (gclock_my_date(), read from stop_log). A bar that reaches 100 LATCHES (table stop_marks): it stays full, its perk
 * (data/stop_perks.txt, generated by claude/tools_export_stop_perks.py) is the gnome's for good. Unfilled bars lose `mark_decay`
 * a game day (default 0 = never). Old meters are migrated on first read: the old decay one last time on the gnome's date, then frozen.
 * No mark is ever given for a past fill (a stored meter is at most 99). Old 7-day perks run out on their own date; the setting
 * `perk_old_retired` switches them off for good (player_perks.php).
 *
 * Stops: villages; with the setting on also the market towns and havens (stop_is_place). Their type: Admin (locations.stop_type),
 * else MARK_PLACE_TYPES, else the catalogue.
 *
 * HOOK API for the call sites (nothing below gives power until a call site asks):
 *   stop_marks_active(int $uid): bool                       lasting marks are on for this gnome
 *   mark_pct(int $uid, string $family, array $ctx = []): int  world marks of the family (capped, MARK_FAMILIES) + place marks that fit
 *                                                            $ctx (capped by MARK_PLACE_STACK, rule P2). Always >= 0, in the family's
 *                                                            unit; the family says which way it works (walk 6 = 6% less time).
 *   mark_place(int $uid, string $family, array $ctx = []): int  only the place part of mark_pct
 *   mark_daily_available(int $uid, string $perkKey): bool   a held daily charge (A1-A3) not yet used this game day
 *   mark_daily_use(int $uid, string $perkKey): bool          takes it (once per game day; false if gone or not held)
 *   mark_daycoin(int $uid, string $perkKey, int $coins): int A4 coins allowed now (all A4 perks share MARK_A4_CEILING a game day)
 *   mark_flag(int $uid, string $keyOrFamily): bool           a held flag perk by key, or any of a flag family ('info'/'A5', 'looks'/'A6')
 *   $family: a short name (sell, buy, xp, gxp, walk, cook, meal, buff, heal, harvest, gather, water, seed, friend, stopcoin, check,
 *   pest, travel, spot, hp, torch, restenergy, trailseed) or its code F01-F23.
 *   $ctx keys (MARK_SCOPE_KEYS): from / to / at = location ids; region = region code; land, type (stop type), kind (act kind),
 *   group (item group words), items (crop slugs), delve (slug of the delve name), route; we / dp / se default to the gnome's clock.
 *   A scope value 'here' is the perk's own stop; `from=here` also fits an act done at that stop (ctx at). A perk whose scope names a
 *   key the caller does not pass does not apply. Until perk_old_retired, a call site takes the larger of the old 7-day perk and
 *   mark_pct, never both (proposal-stop-perks.md section 8, migration 2).
 */

require_once __DIR__ . '/stop_living.php';

const MARK_BARS = ['repairs' => 'Mended', 'larder' => 'Stocked', 'cheer' => 'Merry'];   // stamp words (proposal 7)
/** code => [short name, unit, world cap] (proposal-stop-perks.md 4). */
const MARK_FAMILIES = [
    'F01' => ['sell', '%', 5], 'F02' => ['buy', '%', 5], 'F03' => ['xp', '%', 5], 'F04' => ['gxp', '%', 5], 'F05' => ['walk', '%', 6],
    'F06' => ['cook', '%', 6], 'F07' => ['meal', '%', 5], 'F08' => ['buff', '%', 8], 'F09' => ['heal', '%', 8], 'F10' => ['harvest', '%', 4],
    'F11' => ['gather', '%', 4], 'F12' => ['water', '%', 8], 'F13' => ['seed', '%', 4], 'F14' => ['friend', '%', 8], 'F15' => ['stopcoin', '%', 8],
    'F16' => ['check', '%', 4], 'F17' => ['pest', '%', 8], 'F18' => ['travel', '%', 5], 'F19' => ['spot', '%', 4], 'F20' => ['hp', 'pt', 3],
    'F21' => ['torch', 'step', 3], 'F22' => ['restenergy', 'energy', 2], 'F23' => ['trailseed', '%', 4],
];
/** Rule P2: what the place perks of one family may add at one event, on top of the world total. */
const MARK_PLACE_STACK = ['F03' => 2, 'F20' => 1, 'F21' => 1, 'F22' => 1];
const MARK_PLACE_STACK_DEFAULT = 4;
const MARK_A4_CEILING = 10;   // coins a game day from all A4 perks together
const MARK_FLAG_FAMILIES = ['info' => 'A5', 'looks' => 'A6'];
const MARK_SCOPE_KEYS = ['from', 'to', 'at', 'region', 'land', 'type', 'kind', 'group', 'items', 'delve', 'route', 'we', 'dp', 'se'];
const MARK_ANSWER_ACTS = ['mend_board', 'tidy_yard', 'fill_shelf', 'hang_lanterns'];
const MARK_TYPE_LEAN = ['market' => 'larder', 'mill' => 'repairs', 'inn' => 'larder', 'shrine' => 'repairs', 'jetty' => 'repairs', 'herb' => 'larder',
    'workshop' => 'repairs', 'orchard' => 'larder', 'ferry' => 'repairs', 'tower' => 'larder', 'spring' => 'repairs', 'camp' => 'larder'];   // proposal 2, step 3
/** Stop types of the Maplewold town and havens (master 7.5); Admin's locations.stop_type wins. Other towns and havens: the catalogue. */
const MARK_PLACE_TYPES = ['market-na' => 'market', 'lm-na-1-haven-the-sugar-shack' => 'orchard', 'lm-na-4-haven-aurora-camp' => 'camp'];

function stop_marks_on(): bool
{
    return setting('stop_marks_open') === '1';
}

function stop_marks_active(int $uid): bool
{
    return $uid > 0 && stop_marks_on();
}

/** A rest stop: every village; with lasting marks on, also a market town or haven that has a stop type. */
function stop_is_place(array $loc): bool
{
    $k = (string)($loc['kind'] ?? '');
    if ($k === 'village') return true;
    return in_array($k, ['market', 'haven'], true) && stop_marks_on() && mark_place_type($loc) !== '';
}

/** The stop type of a market town or haven: Admin's, else MARK_PLACE_TYPES, else its catalogue row ('' = none). */
function mark_place_type(array $loc): string
{
    $t = (string)($loc['stop_type'] ?? '');
    if ($t !== '' && isset(stop_types()[$t])) return $t;
    if (isset(MARK_PLACE_TYPES[(string)($loc['slug'] ?? '')])) return MARK_PLACE_TYPES[(string)$loc['slug']];
    foreach (mark_catalogue() as $p) if ($p['loc_id'] === (int)($loc['id'] ?? 0)) return $p['type'];
    return '';
}

// ---------------------------------------------------------------- catalogue

/** "a=b,c/d=e" => ['a' => ['b', 'c'], 'd' => ['e']]; '-' => []. */
function mark_scope_parse(string $s): array
{
    $out = [];
    if ($s === '' || $s === '-') return $out;
    foreach (explode('/', $s) as $part) {
        [$k, $v] = array_pad(explode('=', trim($part), 2), 2, '');
        if ($k !== '') $out[$k] = array_values(array_filter(array_map('trim', explode(',', $v)), fn($x) => $x !== ''));
    }
    return $out;
}

/** @return array<string,array> data/stop_perks.txt by perk key, each with loc_id (0 = no such place in this world yet). */
function mark_catalogue(): array
{
    static $c = null;
    if ($c !== null) return $c;
    $bySlug = $byName = [];
    foreach (q("SELECT id, slug, name FROM locations WHERE kind IN ('village', 'market', 'haven')")->fetchAll() as $l) {
        $bySlug[(string)$l['slug']] = (int)$l['id'];
        $byName[mark_name_key((string)$l['name'])] = (int)$l['id'];
    }
    $c = [];
    foreach (stops_file_rows('stop_perks.txt') as $r) {
        if (count($r) < 14) continue;
        $c[$r[0]] = ['key' => $r[0], 'region' => $r[1], 'stop' => $r[2], 'type' => $r[4], 'bar' => $r[5], 'icon' => $r[6], 'name' => $r[7],
            'effect' => $r[8], 'family' => $r[9], 'class' => $r[10], 'scope' => mark_scope_parse($r[11]), 'size' => (int)$r[12], 'impact' => (float)$r[13], 'hook' => $r[14] ?? 'site',
            'loc_id' => $bySlug[$r[3]] ?? ($byName[mark_name_key($r[2])] ?? 0)];
    }
    return $c;
}

function mark_name_key(string $name): string
{
    return strtolower(preg_replace('/^The /', '', trim($name)));
}

/** The perk a stop's bar earns (catalogue row), or null (a stop added later: Admin picks one). */
function mark_perk_for(int $locId, string $bar): ?array
{
    foreach (mark_catalogue() as $p) if ($p['loc_id'] === $locId && $p['bar'] === $bar) return $p;
    return null;
}

// ---------------------------------------------------------------- bars

/** @return array<string,array> the gnome's latched bars at a stop: bar => stop_marks row. */
function mark_latched(int $uid, int $locId, bool $refresh = false): array
{
    static $cache = [];
    $k = $uid . ':' . $locId;
    if ($refresh || !isset($cache[$k])) {
        $cache[$k] = [];
        foreach (q('SELECT * FROM stop_marks WHERE user_id = ? AND location_id = ?', [$uid, $locId])->fetchAll() as $r) $cache[$k][(string)$r['bar']] = $r;
    }
    return $cache[$k];
}

/** A bar now, 0-100. A latched bar is 100 for good. An old meter is migrated on first read (old decay once, then frozen). */
function mark_bar_get(int $uid, int $locId, string $bar): int
{
    if (isset(mark_latched($uid, $locId)[$bar])) return 100;
    [$n, $d] = stop_prog_get($uid, $locId, 'meter:' . $bar);
    $today = gclock_my_date();
    $since = (string)($d['d'] ?? '');
    $age = $since !== '' ? stop_days_between($since, $today) : 0;
    if ($since !== '' && empty($d['mk'])) {   // migration: the last old decay, on the gnome's own date; from now on mark_decay
        $n = max(0, min(99, $n - STOP_METER_DECAY * $age));
        stop_prog_set($uid, $locId, 'meter:' . $bar, $n, ['d' => $today, 'mk' => 1]);
        return $n;
    }
    return max(0, min(99, $n - max(0, (int)setting('mark_decay')) * $age));
}

/** Add points to a bar. Returns [value now, the perk row when this add latched it (else null)]. A latched bar counts one more "kept up". */
function mark_bar_add(int $uid, array $loc, string $bar, int $pts): array
{
    $lid = (int)$loc['id'];
    if (isset(mark_latched($uid, $lid)[$bar])) {
        q('UPDATE stop_marks SET kept = kept + 1 WHERE user_id = ? AND location_id = ? AND bar = ?', [$uid, $lid, $bar]);
        mark_latched($uid, $lid, true);
        return [100, null];
    }
    $v = mark_bar_get($uid, $lid, $bar) + max(0, $pts);
    if ($v < 100) {
        stop_prog_set($uid, $lid, 'meter:' . $bar, $v, ['d' => gclock_my_date(), 'mk' => 1]);
        return [$v, null];
    }
    $perk = mark_perk_for($lid, $bar);
    try {
        db_insert('stop_marks', ['user_id' => $uid, 'location_id' => $lid, 'bar' => $bar, 'perk_key' => $perk['key'] ?? '', 'filled_on' => gclock_my_date(), 'latched_at' => now(), 'kept' => 0]);
    } catch (PDOException $e) {   // a second request latched it first
        mark_latched($uid, $lid, true);
        return [100, null];
    }
    stop_prog_set($uid, $lid, 'meter:' . $bar, 100, ['d' => gclock_my_date(), 'mk' => 1]);
    mark_latched($uid, $lid, true);
    mark_held($uid, true);
    return [100, $perk ?? ['key' => '', 'icon' => '🏅', 'name' => 'A lasting mark', 'effect' => '']];
}

/** @return array<string,array{0:string,1:string}> data/stop_act_bars.txt: "slug|type" => [first bar, second bar or '']. */
function mark_act_bar_table(): array
{
    static $t = null;
    if ($t === null) {
        $t = [];
        foreach (stops_file_rows('stop_act_bars.txt') as $r) if (count($r) >= 4) $t[$r[0] . '|' . $r[1]] = [$r[2], $r[3] === '-' ? '' : $r[3]];
    }
    return $t;
}

/** [first bar, second bar or ''] of an act at a stop type. An act missing from the table (made in Admin): its old meter, else the type's lean. */
function mark_act_bars(array $a, string $type): array
{
    $t = mark_act_bar_table();
    $slug = (string)($a['slug'] ?? '');
    if (isset($t[$slug . '|' . $type])) return $t[$slug . '|' . $type];
    if (isset($t[$slug . '|*'])) return $t[$slug . '|*'];
    $old = stop_act_moves($a)[0][0] ?? '';
    return [$old !== '' ? $old : (MARK_TYPE_LEAN[$type] ?? 'cheer'), ''];
}

/** B: points by the act's energy cost (settings mark_pts_0..3). */
function mark_base_points(array $a): int
{
    return max(0, (int)setting('mark_pts_' . min(3, max(0, (int)($a['energy'] ?? 0)))));
}

/**
 * Points for an act just done (it is already in stop_log), master 7.3: pts = max(1, floor(B x D x W x F)) + V; second bar floor(pts / 2), at least 1;
 * the first full round of a game day at a stop gives +mark_round to its lowest unfilled bar. Returns [bar => points].
 */
function mark_points(int $uid, array $loc, array $a, string $note, bool $fest): array
{
    $type = stop_type_of($loc);
    $slug = (string)$a['slug'];
    [$first, $second] = mark_act_bars($a, $type);
    $prior = array_values(array_filter(q('SELECT act, kind FROM stop_log WHERE user_id = ? AND location_id = ? AND day = ? ORDER BY id', [$uid, (int)$loc['id'], gclock_my_date()])->fetchAll(),
        fn($r) => (string)$r['act'] !== $slug));
    $acts = stop_acts();
    $nth = 1;
    $fedBefore = [];
    $kindSeen = false;
    foreach ($prior as $r) {
        $pa = $acts[(string)$r['act']] ?? ['slug' => (string)$r['act']];
        [$f, $s] = mark_act_bars($pa, $type);
        if ($f === $first) $nth++;
        $fedBefore[$f] = true;
        if ($s !== '') $fedBefore[$s] = true;
        if ((string)$r['kind'] === (string)$a['kind']) $kindSeen = true;
    }
    $d = $nth === 1 ? 1.0 : ($nth === 2 ? max(0, (int)setting('mark_repeat_pct')) / 100 : 0.0);
    $lost = (bool)preg_match('/(^|\s)miss$|^seen /', $note);
    $w = $lost ? max(0, (int)setting('mark_lose_pct')) / 100 : 1.0;
    $f = ($fest ? max(1, (int)setting('mark_fest_mult')) : 1) * (in_array($slug, MARK_ANSWER_ACTS, true) ? max(100, (int)setting('mark_answer_pct')) / 100 : 1.0);
    $pts = max(1, (int)floor(mark_base_points($a) * $d * $w * $f)) + ($kindSeen ? 0 : max(0, (int)setting('mark_variety')));
    $out = [$first => $pts];
    if ($second !== '') $out[$second] = max(1, intdiv($pts, 2));
    if (count($fedBefore) < 3 && count($fedBefore + $out) === 3) {   // the first full round today
        $lowest = null;
        foreach (array_keys(MARK_BARS) as $b) {
            if (isset(mark_latched($uid, (int)$loc['id'])[$b])) continue;
            $v = mark_bar_get($uid, (int)$loc['id'], $b) + ($out[$b] ?? 0);
            if ($lowest === null || $v < $lowest[1]) $lowest = [$b, $v];
        }
        if ($lowest !== null) $out[$lowest[0]] = ($out[$lowest[0]] ?? 0) + max(0, (int)setting('mark_round'));
    }
    return $out;
}

/** After a done act, with lasting marks on: feed its bars, latch a bar at 100. Returns the lines to show. */
function mark_after(array $u, array $loc, array $a, string $note, bool $fest): array
{
    $uid = (int)$u['id'];
    $lines = [];
    foreach (mark_points($uid, $loc, $a, $note, $fest) as $bar => $pts) {
        $was = isset(mark_latched($uid, (int)$loc['id'])[$bar]);
        [, $perk] = mark_bar_add($uid, $loc, $bar, $pts);
        $lines[] = STOP_METERS[$bar][0] . ' ' . STOP_METERS[$bar][1] . ($was ? ' kept up' : ' +' . $pts);
        if ($perk) $lines[] = '🌟 ' . STOP_METERS[$bar][1] . ' is ' . strtolower(MARK_BARS[$bar]) . ' at ' . $loc['name'] . ', for good. ' . trim($perk['icon'] . ' ' . $perk['name'] . ($perk['effect'] !== '' ? ': ' . $perk['effect'] : '')) . '.';
    }
    return $lines;
}

// ---------------------------------------------------------------- hooks

/** @return list<array> the catalogue rows of every mark the gnome holds, each with its 'kept' count (cached per request). */
function mark_held(int $uid, bool $refresh = false): array
{
    static $cache = [];
    if (!$refresh && isset($cache[$uid])) return $cache[$uid];
    $cat = mark_catalogue();
    $out = [];
    try {
        foreach (q("SELECT perk_key, location_id, bar, kept, filled_on FROM stop_marks WHERE user_id = ? AND perk_key <> '' ORDER BY latched_at DESC, location_id", [$uid])->fetchAll() as $r) {
            if (isset($cat[$r['perk_key']])) $out[] = $cat[$r['perk_key']] + ['kept' => (int)$r['kept'], 'filled_on' => (string)$r['filled_on']];
        }
    } catch (PDOException $e) { $out = []; }   // table not made yet (before Upgrade database)
    return $cache[$uid] = $out;
}

/** A family's code (F01...) from its code or short name; '' if unknown. */
function mark_family_code(string $family): string
{
    if (isset(MARK_FAMILIES[$family])) return $family;
    foreach (MARK_FAMILIES as $code => [$name]) if ($name === $family) return $code;
    return '';
}

/** Does a perk's scope fit this event? Every key the perk names must match $ctx (we / dp / se fall back to the gnome's clock). */
function mark_scope_fits(array $p, array $ctx): bool
{
    foreach ($p['scope'] as $k => $vals) {
        if (!in_array($k, MARK_SCOPE_KEYS, true)) continue;   // trig=, page=: where a hook goes, not a condition
        $vals = array_map(fn($v) => $v === 'here' ? (string)$p['loc_id'] : $v, $vals);
        $have = match ($k) {
            'we' => $ctx['we'] ?? gclock_my_weather(isset($ctx['region']) ? (string)$ctx['region'] : null),
            'dp' => $ctx['dp'] ?? hollow_daypart(),
            'se' => $ctx['se'] ?? hollow_season(),
            'from' => array_merge((array)($ctx['from'] ?? []), (array)($ctx['at'] ?? [])),
            default => $ctx[$k] ?? null,
        };
        if ($have === null || !array_intersect(array_map('strval', (array)$have), $vals)) return false;
    }
    return true;
}

/** [world sum capped, place sum capped] of a family's held number perks that fit $ctx. */
function mark_sums(int $uid, string $family, array $ctx): array
{
    $code = mark_family_code($family);
    if ($code === '' || !stop_marks_active($uid)) return [0, 0];
    $world = $place = 0;
    foreach (mark_held($uid) as $p) {
        if ($p['family'] !== $code || !in_array($p['class'], ['W', 'P'], true) || !mark_scope_fits($p, $ctx)) continue;
        if ($p['class'] === 'W') $world += abs($p['size']); else $place += abs($p['size']);
    }
    return [min($world, MARK_FAMILIES[$code][2]), min($place, MARK_PLACE_STACK[$code] ?? MARK_PLACE_STACK_DEFAULT)];
}

function mark_pct(int $uid, string $family, array $ctx = []): int
{
    return array_sum(mark_sums($uid, $family, $ctx));
}

function mark_place(int $uid, string $family, array $ctx = []): int
{
    return mark_sums($uid, $family, $ctx)[1];
}

/** A held perk of one class by key, or null. */
function mark_held_perk(int $uid, string $perkKey, string $class): ?array
{
    if (!stop_marks_active($uid)) return null;
    foreach (mark_held($uid) as $p) if ($p['key'] === $perkKey && $p['class'] === $class) return $p;
    return null;
}

function mark_daily_available(int $uid, string $perkKey): bool
{
    return mark_held_perk($uid, $perkKey, 'D') !== null
        && !q_val('SELECT 1 FROM stop_mark_use WHERE user_id = ? AND day = ? AND perk_key = ?', [$uid, gclock_my_date(), $perkKey]);
}

function mark_daily_use(int $uid, string $perkKey): bool
{
    if (!mark_daily_available($uid, $perkKey)) return false;
    try {
        db_insert('stop_mark_use', ['user_id' => $uid, 'day' => gclock_my_date(), 'perk_key' => $perkKey, 'used' => 1]);
    } catch (PDOException $e) {
        return false;   // another request took it this game day
    }
    return true;
}

/** A4: how many of $coins this perk may give now; all A4 perks share MARK_A4_CEILING a game day (row perk_key 'a4', used = coins given). */
function mark_daycoin(int $uid, string $perkKey, int $coins): int
{
    $p = mark_held_perk($uid, $perkKey, 'D');
    if (!$p || $p['family'] !== 'A4' || $coins < 1) return 0;
    $day = gclock_my_date();
    $used = (int)q_val("SELECT used FROM stop_mark_use WHERE user_id = ? AND day = ? AND perk_key = 'a4'", [$uid, $day]);
    $give = min($coins, MARK_A4_CEILING - $used);
    if ($give < 1) return 0;
    if ($used === 0) {
        try { db_insert('stop_mark_use', ['user_id' => $uid, 'day' => $day, 'perk_key' => 'a4', 'used' => $give]); return $give; }
        catch (PDOException $e) { /* made by another request: fall through to the guarded update */ }
    }
    return q("UPDATE stop_mark_use SET used = used + ? WHERE user_id = ? AND day = ? AND perk_key = 'a4' AND used + ? <= ?", [$give, $uid, $day, $give, MARK_A4_CEILING])->rowCount() === 1 ? $give : 0;
}

function mark_flag(int $uid, string $keyOrFamily): bool
{
    if (!stop_marks_active($uid)) return false;
    $fam = MARK_FLAG_FAMILIES[$keyOrFamily] ?? $keyOrFamily;
    foreach (mark_held($uid) as $p) if ($p['class'] === 'F' && ($p['key'] === $keyOrFamily || $p['family'] === $fam)) return true;
    return false;
}

// ---------------------------------------------------------------- UI

/** The three bars for the Do tab: a meter each with the perk it is for (greyed), or the stamp of a full bar. */
function mark_bars_html(int $uid, int $lid): string
{
    $h = '<ul class="st-meters mk-bars">';
    foreach (STOP_METERS as $bar => [$ico, $lab]) {
        $perk = mark_perk_for($lid, $bar);
        $pname = $perk ? $perk['icon'] . ' ' . $perk['name'] : '';
        if (isset(mark_latched($uid, $lid)[$bar])) {
            $h .= '<li class="mk-full"><span>' . $ico . ' ' . e($lab) . '</span> <b class="mk-stamp">' . e(strtoupper(MARK_BARS[$bar])) . ' ✔</b>' . ($pname !== '' ? ' <small>' . e($pname) . '</small>' : '') . '</li>';
            continue;
        }
        $v = mark_bar_get($uid, $lid, $bar);
        $h .= '<li><label>' . $ico . ' ' . e($lab) . ' <meter min="0" max="100" low="30" high="70" optimum="100" value="' . $v . '">' . $v . '%</meter> ' . $v . '%</label>'
            . ($pname !== '' ? ' <small class="muted">· ' . e($pname) . '</small>' : '') . '</li>';
    }
    return $h . '</ul>';
}

/** Plaque lines under a stop's name, one per full bar: "🪧 The Straightened Signpost: Mended by Bramble. Kept up 12 times." */
function mark_plaque_html(array $u, array $loc): string
{
    $uid = (int)$u['id'];
    $h = '';
    foreach (mark_latched($uid, (int)$loc['id']) as $bar => $r) {
        $perk = mark_perk_for((int)$loc['id'], $bar);
        $h .= '<p class="mk-plaque">' . e(($perk ? $perk['icon'] . ' ' . $perk['name'] : STOP_METERS[$bar][0] . ' ' . STOP_METERS[$bar][1]) . ': ' . MARK_BARS[$bar] . '. '
            . ((string)($u['gnome_name'] ?? '') ?: (string)($u['username'] ?? 'You')) . ' saw to it.' . ((int)$r['kept'] > 0 ? ' Kept up ' . (int)$r['kept'] . ' time' . ((int)$r['kept'] === 1 ? '' : 's') . '.' : '')) . '</p>';
    }
    return $h;
}

/** The "Lasting marks" card of the Perks page: per stop with progress, three pips and the names of its latched perks; then the totals. */
function mark_card_html(int $uid): string
{
    $held = mark_held($uid);
    $na = count(array_filter($held, fn($p) => in_array($p['region'], ['NA'], true) || in_array($p['stop'], ['Larkbrook', 'Windbottom', 'Honeythorpe'], true)));
    $h = '<h4>🏅 Lasting marks <small class="muted">' . $na . ' of 54 on the Maplewold roads · ' . count($held) . ' in all</small></h4>';
    $stops = q("SELECT DISTINCT l.id, l.name FROM stop_prog p JOIN locations l ON l.id = p.location_id WHERE p.user_id = ? AND p.k LIKE 'meter:%' ORDER BY l.name", [$uid])->fetchAll();
    if (!$stops) return $h . '<div class="pkempty"><span>No marks yet. Fill a bar at any stop and its perk is yours for good.</span></div>';
    $h .= '<ul class="mk-list">';
    foreach ($stops as $s) {
        $lid = (int)$s['id'];
        $pips = $names = '';
        foreach (STOP_METERS as $bar => [$ico, $lab]) {
            $v = mark_bar_get($uid, $lid, $bar);
            $pips .= '<i class="mk-pip' . ($v >= 100 ? ' on' : '') . '" title="' . e($lab . ' ' . $v . '%') . '"></i>';
            if ($v >= 100 && ($p = mark_perk_for($lid, $bar))) $names .= ' <span class="mk-name">' . e($p['icon'] . ' ' . $p['name']) . '</span>';
        }
        $h .= '<li><b>' . e((string)$s['name']) . '</b> <span class="mk-pips">' . $pips . '</span>' . $names . '</li>';
    }
    $h .= '</ul>';
    $sum = [];
    foreach (MARK_FAMILIES as $code => [$name, $unit, $cap]) {
        $w = 0;
        foreach ($held as $p) if ($p['family'] === $code && $p['class'] === 'W') $w += abs($p['size']);
        if ($w > 0) $sum[] = e($name) . ' ' . min($w, $cap) . ($unit === '%' ? '%' : ' ' . $unit) . ' everywhere (most ' . $cap . ')' . ($w >= $cap ? ' · as good as it gets' : '');
    }
    $daily = count(array_filter($held, fn($p) => $p['class'] === 'D'));
    $places = count(array_filter($held, fn($p) => $p['class'] === 'P'));
    if ($sum || $daily || $places) $h .= '<p class="help">Adds up to: ' . implode(' · ', array_merge($sum, $daily ? [$daily . ' daily charge' . ($daily === 1 ? '' : 's')] : [], $places ? [$places . ' place' . ($places === 1 ? '' : 's')] : [])) . '</p>';
    return $h;
}

/** The Perks popover's list for one stop: each bar's perk, earned (gold) or what it is for (greyed). */
function mark_stop_perks_html(int $uid, int $lid): string
{
    $h = '';
    foreach (STOP_METERS as $bar => [$ico, $lab]) {
        $p = mark_perk_for($lid, $bar);
        if (!$p) continue;
        $full = isset(mark_latched($uid, $lid)[$bar]);
        $h .= '<div class="pkperk' . ($full ? '' : ' mk-off') . '"><span class="pkbadge">' . e($p['icon']) . '</span><div class="pkpt"><b>' . e($p['name']) . '</b><span class="pkfx">' . e($p['effect']) . '</span></div>'
            . '<div class="pkleft"><small>' . ($full ? e(MARK_BARS[$bar]) . ', for good' : e($lab) . ' ' . mark_bar_get($uid, $lid, $bar) . '%') . '</small></div></div>';
    }
    return $h;
}

/** [[bar, base points], ...] an act feeds at a stop type (for the Perks popover's act list; second bar at half). */
function mark_act_moves(array $a, string $type): array
{
    [$first, $second] = mark_act_bars($a, $type);
    $b = max(1, mark_base_points($a));
    return $second !== '' ? [[$first, $b], [$second, max(1, intdiv($b, 2))]] : [[$first, $b]];
}
